1	import { isAbsolute, matchesGlob, relative, resolve } from 'node:path'
2	import type { PreToolUseOutcome, SessionHooks, ToolUse } from '../session/hooks'
3	import type { SessionEvent } from '../session/code-session'
4	import { isReadOnlyCommand, isReadOnlySegment, type ReadOnlyContext } from './read-only-commands'
5	import { bashPatternMatches, commandLines, isShellTool, parseRule, type PermissionRule } from './permission-rules'
6	import { splitShellCommand, type ShellSegment } from './shell-split'
7	
8	export type PermissionRules = { allow: string[]; deny: string[] }
9	
10	/**
11	 * Tools that only look; their calls never prompt unless a deny rule names them.
12	 * `AskUser` changes nothing either: the person answers the question itself
13	 * rather than first being asked whether it may be put to them.
14	 */
15	const READ_ONLY_TOOLS = new Set(['Read', 'Glob', 'Grep', 'JsonSchema', 'JsonQuery', 'LS', 'NotebookRead', 'TodoRead', 'TodoWrite', 'AskUser'])
16	
17	const FILE_TOOLS = new Set(['Read', 'Write', 'Edit', 'MultiEdit', 'NotebookEdit', 'NotebookRead', 'Glob', 'Grep', 'JsonSchema', 'JsonQuery', 'LS'])
18	
19	/**
20	 * Decides tool calls before any permission prompt, on every engine: a deny
21	 * rule blocks, a read-only call or one covered by the project's allow rules
22	 * goes through, everything else is asked. Rules are read on each call so a
23	 * rule allowed for the session or the project applies to the next call.
24	 */
25	export class PermissionPolicy implements SessionHooks {
26	  private readonly readOnlyContext: ReadOnlyContext
27	
28	  constructor(
29	    private readonly cwd: string,
30	    private readonly rules: () => PermissionRules,
31	  ) {
32	    this.readOnlyContext = { insideProject: (path) => !this.relativeTo(path).startsWith('..') }
33	  }
34	
35	  async preToolUse(tool: ToolUse): Promise<PreToolUseOutcome> {
36	    const { allow, deny } = this.rules()
37	    const denied = deny.find((rule) => this.matches(parseRule(rule), tool, 'any'))
38	    if (denied) return { deny: `Blocked by the project's permission rule ${denied} (kiwiAgent.permissions.deny).` }
39	    if (this.isReadOnly(tool)) return { allow: true }
40	    if (allow.some((rule) => this.matches(parseRule(rule), tool, 'all'))) return { allow: true }
41	    return undefined
42	  }
43	
44	  /** A prompt for a shell call is asked line by line: each command with what the rules in force make of it. */
45	  decorate(event: SessionEvent): SessionEvent {
46	    if (event.type !== 'permission_request' || !isShellTool(event.toolName)) return event
47	    return { ...event, commands: commandLines(event.toolName, this.command(event), this.rules().allow, this.readOnlyContext) }
48	  }
49	
50	  private isReadOnly(tool: ToolUse): boolean {
51	    if (READ_ONLY_TOOLS.has(tool.toolName)) return true
52	    return isShellTool(tool.toolName) && isReadOnlyCommand(this.command(tool), this.readOnlyContext)
53	  }
54	
55	  /**
56	   * For a shell tool, `all` requires the rule to cover every segment (an
57	   * allow), while `any` fires on one (a deny). A substitution hides a command,
58	   * so no allow rule can cover it.
59	   */
60	  private matches(rule: PermissionRule, tool: ToolUse, segments: 'all' | 'any'): boolean {
61	    if (rule.tool !== tool.toolName) return false
62	    if (rule.pattern === undefined) return !isShellTool(tool.toolName) || segments === 'any' || !splitShellCommand(this.command(tool)).substitutes
63	    if (isShellTool(tool.toolName)) {
64	      const parsed = splitShellCommand(this.command(tool))
65	      if (segments === 'all' && parsed.substitutes) return false
66	      const covered = (s: ShellSegment) => bashPatternMatches(rule.pattern!, s.tokens) || (segments === 'all' && isReadOnlySegment(s, this.readOnlyContext))
67	      return segments === 'all' ? parsed.segments.every(covered) : parsed.segments.some(covered)
68	    }
69	    if (FILE_TOOLS.has(tool.toolName)) {
70	      const path = this.relativePath(tool)
71	      return path !== undefined && matchesGlob(path, rule.pattern)
72	    }
73	    return false
74	  }
75	
76	  private command(tool: { input: unknown }): string {
77	    const command = (tool.input as { command?: unknown })?.command
78	    return typeof command === 'string' ? command : ''
79	  }
80	
81	  private relativePath(tool: ToolUse): string | undefined {
82	    const input = (tool.input ?? {}) as Record<string, unknown>
83	    const raw = input['file_path'] ?? input['notebook_path'] ?? input['path']
84	    return typeof raw === 'string' ? this.relativeTo(raw) : undefined
85	  }
86	
87	  private relativeTo(raw: string): string {
88	    const absolute = isAbsolute(raw) ? raw : resolve(this.cwd, raw)
89	    return relative(this.cwd, absolute).split('\\').join('/')
90	  }
91	}
